/** Real permission transitions, ledger transactions, native delivery and context-dependent combat. */
public final class DevPvpChecks {
 private static void check(boolean ok,String why){if(!ok)throw new AssertionError("PvP: "+why);}
 public static void run(ServerPlayer p){var server=p.level().getServer();var d=RpgPlayers.get(p);var saved=d.save();var identity=new net.minecraft.server.players.NameAndId(p.getGameProfile());boolean wasOp=server.getPlayerList().isOp(identity);var oldMode=p.gameMode.getGameModeForPlayer();var before=new ArrayList<ItemStack>();for(var stack:p.getInventory())before.add(stack.copy());
  try{
   if(com.mmorpg.network.NetworkConfig.current.enabled&&!com.mmorpg.network.NetworkPlayers.save(p))check(com.mmorpg.network.NetworkPlayers.login(p),"test player acquires shared-profile lease before purchases");d=RpgPlayers.get(p);
   p.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);server.getPlayerList().deop(identity);d.rankLabel="Fondateur";p.setGameMode(net.minecraft.world.level.GameType.CREATIVE);check(!p.isCreative(),"staff label cannot grant creative without OP");server.getPlayerList().op(identity);p.setGameMode(net.minecraft.world.level.GameType.CREATIVE);check(p.isCreative(),"operator may enter creative");server.getPlayerList().deop(identity);CreativeAccess.enforce(p);check(!p.isCreative(),"deop immediately returns creative player to survival");
   for(var cls:PlayerClass.values()){if(cls==PlayerClass.NONE)continue;var learner=new com.mmorpg.rpg.PlayerData();learner.playerClass=cls;learner.level=100;learner.unlockSkills();int required=com.mmorpg.skill.Skills.forClass(cls).size()*(com.mmorpg.skill.Skill.MAX_RANK-1);check(learner.availableSkillPoints()==required,"level 100 budget maximizes every skill of "+cls);for(var skill:com.mmorpg.skill.Skills.forClass(cls))learner.skillRanks.put(skill.id,com.mmorpg.skill.Skill.MAX_RANK);check(learner.availableSkillPoints()==0&&learner.spentSkillPoints()==required,"all maximum ranks exactly consume budget");}
   var window=new com.mmorpg.combat.CrowdControl.Window();check(window.allow(100)&&window.allow(100),"one impulse may contain native and custom components");check(window.allow(120)&&window.allow(140),"three distinct projections accepted");check(!window.allow(141)&&!window.allow(339),"ten-second immunity after third projection");check(window.allow(340),"control returns after full ten seconds");
   check(com.mmorpg.item.ItemDefs.SETS.keySet().stream().filter(id->id.startsWith("pvp_")).count()==20,"one PvP set per class and level bracket");check(com.mmorpg.item.ItemDefs.WEAPONS.stream().filter(w->w.id().startsWith("pvp_")).count()==20,"one PvP weapon per class and bracket");for(var product:PvpProgression.products())if(!product.item().isEmpty())check(com.mmorpg.crafting.ForgeRecipes.resolveItem("mmorpg:"+product.item())!=Items.AIR,"real registered PvP product "+product.item());
   p.getInventory().clearContent();d.playerClass=PlayerClass.MAGE;d.level=100;
   var slots=new net.minecraft.world.entity.EquipmentSlot[]{net.minecraft.world.entity.EquipmentSlot.HEAD,net.minecraft.world.entity.EquipmentSlot.CHEST,net.minecraft.world.entity.EquipmentSlot.LEGS,net.minecraft.world.entity.EquipmentSlot.FEET};for(int i=0;i<4;i++)p.setItemSlot(slots[i],new ItemStack(ModItems.get("pvp_mage_4_"+com.mmorpg.item.ItemDefs.PIECES[i])));p.setItemSlot(net.minecraft.world.entity.EquipmentSlot.MAINHAND,new ItemStack(ModItems.get("pvp_mage_4_arme")));
   check(PvpEquipment.pieces(p)==4&&PvpEquipment.outgoing(p,true)>1&&PvpEquipment.outgoing(p,false)<1,"equipment stronger against players and weaker against mobs");check(PvpEquipment.incoming(p,true)<1&&PvpEquipment.incoming(p,false)>1,"PvP resilience has a PvE tradeoff");
   d.playerClass=PlayerClass.GUERRIER;check(PvpEquipment.pieces(p)==0&&PvpEquipment.outgoing(p,true)==1,"wrong class equipment grants no PvP bonus");d.playerClass=PlayerClass.MAGE;d.level=1;check(PvpEquipment.pieces(p)==0,"underlevel equipment grants no PvP bonus");d.level=100;
   PvpProgression.access(server,s->{PvpProgression.account(s,p.getUUID()).points=5000;return null;});var request=UUID.randomUUID();PvpProgression.buy(p,"soin",request,30);long balance=PvpProgression.access(server,s->PvpProgression.account(s,p.getUUID()).points);int potions=p.getInventory().countItem(ModItems.POTION_SOIN_MAJEURE.get());PvpProgression.buy(p,"soin",request,30);check(balance==4970&&PvpProgression.access(server,s->PvpProgression.account(s,p.getUUID()).points)==balance&&p.getInventory().countItem(ModItems.POTION_SOIN_MAJEURE.get())==potions,"replayed purchase neither debits nor delivers twice");
   for(int i=0;i<36;i++)p.getInventory().setItem(i,new ItemStack(Items.STONE,64));PvpProgression.buy(p,"mana",UUID.randomUUID(),30);check(PvpProgression.access(server,s->PvpProgression.account(s,p.getUUID()).pending.size())==1,"full inventory preserves paid delivery");p.getInventory().setItem(5,ItemStack.EMPTY);PvpProgression.deliver(p);check(PvpProgression.access(server,s->PvpProgression.account(s,p.getUUID()).pending.isEmpty())&&p.getInventory().getItem(5).is(ModItems.POTION_MANA_MAJEURE.get()),"pending item reaches available slot");
   boolean denied=false;try{PvpProgression.buy(p,"pvp_guerrier_0_arme",UUID.randomUUID(),180);}catch(IllegalArgumentException e){denied=true;}check(denied,"wrong class purchase refused");denied=false;try{PvpProgression.buy(p,"soin",UUID.randomUUID(),1);}catch(IllegalArgumentException e){denied=true;}check(denied,"forged client price refused");
   PvpProgression.buy(p,"monture",UUID.randomUUID(),3500);check(d.mounts.contains("chimere_arene"),"exclusive mount delivered to permanent collection");var after=d.save();d.load(after);check(d.mounts.contains("chimere_arene"),"mount survives profile reload");
   var session=new ArenaManager.Session(new ArenaManager.Key(ArenaRules.Kind.DUNES,0),0);UUID opponent=UUID.randomUUID();session.match.teams.put(p.getUUID(),0);session.match.teams.put(opponent,1);for(UUID id:session.match.teams.keySet()){var c=session.match.contribution(id);c.kills=2;c.strikes=10;c.damage=1000;c.healing=300;}session.match.red=500;session.match.blue=150;session.match.ended=true;long old=PvpProgression.access(server,s->PvpProgression.account(s,p.getUUID()).points);PvpProgression.finish(session,server);long gain=PvpProgression.access(server,s->PvpProgression.account(s,p.getUUID()).points)-old;long loser=PvpProgression.access(server,s->PvpProgression.account(s,opponent).points);check(gain==loser*2&&loser>0,"same contribution earns exactly twice the points on winning team");PvpProgression.finish(session,server);check(PvpProgression.access(server,s->PvpProgression.account(s,p.getUUID()).points)==old+gain,"match payout idempotent");
   boolean featureBefore=FeatureFlags.enabled(server,"boutique_pvp");long safeBalance=PvpProgression.access(server,st->PvpProgression.account(st,p.getUUID()).points);try{FeatureFlags.set(server,"boutique_pvp",false);boolean disabled=false;try{PvpProgression.buy(p,"soin",UUID.randomUUID(),30);}catch(IllegalArgumentException ex){disabled=true;}check(disabled&&PvpProgression.access(server,st->PvpProgression.account(st,p.getUUID()).points)==safeBalance,"runtime disable blocks purchases before any debit");FeatureFlags.set(server,"boutique_pvp",true);check(FeatureFlags.enabled(server,"boutique_pvp"),"runtime re-enable requires no restart");}finally{FeatureFlags.set(server,"boutique_pvp",featureBefore);}
   server.getPlayerList().op(identity);d.playerClass=PlayerClass.TANK;d.level=100;d.shieldGuard=100;d.shieldGuardRecovering=false;p.setItemSlot(net.minecraft.world.entity.EquipmentSlot.MAINHAND,new ItemStack(ModItems.get("marteau_egide")));PaladinOffhand.maintain(p);RpgPlayers.recompute(p);check(com.mmorpg.combat.ShieldGuard.canStart(p),"paladin guard requires actual bound shield and class weapon");var shield=p.getOffhandItem();shield.getItem().use(p.level(),p,net.minecraft.world.InteractionHand.OFF_HAND);check(p.isUsingItem()&&p.getUsedItemHand()==net.minecraft.world.InteractionHand.OFF_HAND,"blocking animation uses shield hand");
   var attacker=net.neoforged.neoforge.common.util.FakePlayerFactory.get(p.level(),new com.mojang.authlib.GameProfile(UUID.randomUUID(),"GuardChecks"));p.setYRot(0);attacker.snapTo(p.getX(),p.getY(),p.getZ()+2,180,0);double hit=com.mmorpg.combat.ShieldGuard.absorb(p,p.damageSources().playerAttack(attacker),100);check(hit<100&&d.shieldGuard<100,"frontal hit consumes guard and reduces incoming damage");for(int n=0;n<55;n++)com.mmorpg.combat.ShieldGuard.absorb(p,p.damageSources().playerAttack(attacker),100);check(d.shieldGuard==0&&!p.isUsingItem()&&!com.mmorpg.combat.ShieldGuard.canStart(p),"exhaustion lowers shield and prevents permanent guard");var guardClock=p.level().getGameTime();try{for(int n=0;n<199;n++){com.mmorpg.combat.ShieldGuard.update(p,guardClock+41+n);}check(d.shieldGuard<100&&!com.mmorpg.combat.ShieldGuard.canStart(p),"broken shield requires full recharge");com.mmorpg.combat.ShieldGuard.update(p,guardClock+240);check(d.shieldGuard==100&&!d.shieldGuardRecovering&&com.mmorpg.combat.ShieldGuard.canStart(p),"full recharge restores guard");}finally{}for(int tier=0;tier<5;tier++)check(com.mmorpg.combat.ShieldGuard.hitCost(new int[]{1,25,50,75,100}[tier])==new int[]{25,20,15,10,2}[tier],"fixed shield cost by evolution tier");
   p.setItemSlot(net.minecraft.world.entity.EquipmentSlot.MAINHAND,new ItemStack(ModItems.get("epee_recrue")));d.shieldGuard=100;check(!com.mmorpg.combat.ShieldGuard.canStart(p),"sword cannot substitute for paladin shield setup");
   var spawn=server.getLevel(com.mmorpg.hub.SpawnBuilder.DIM);var display=net.minecraft.world.entity.EntityTypes.ARMOR_STAND.create(spawn,net.minecraft.world.entity.EntitySpawnReason.COMMAND);display.setItemSlot(net.minecraft.world.entity.EquipmentSlot.HEAD,new ItemStack(Items.DIAMOND_HELMET));server.getPlayerList().deop(identity);var interaction=new net.neoforged.neoforge.event.entity.player.PlayerInteractEvent.EntityInteract(p,net.minecraft.world.InteractionHand.MAIN_HAND,display,net.minecraft.world.phys.Vec3.ZERO);net.neoforged.neoforge.common.NeoForge.EVENT_BUS.post(interaction);check(interaction.isCanceled(),"non-OP cannot interact with spawn armor stand");check(!display.hurtServer(spawn,p.damageSources().playerAttack(p),1000)&&!display.getItemBySlot(net.minecraft.world.entity.EquipmentSlot.HEAD).isEmpty(),"non-OP attack cannot break spawn display or drop equipment");server.getPlayerList().op(identity);check(!com.mmorpg.hub.SpawnDecorProtection.blocked(p,display),"OP keeps access to spawn display editor");display.discard();
   check(PvpProgression.reward(new ArenaRules.Match.Contribution(),true)==0,"idle player earns no participation farming points");session.test=true;session.match.contribution(p.getUUID()).damage+=10000;PvpProgression.finish(session,server);check(PvpProgression.access(server,s->PvpProgression.account(s,p.getUUID()).points)==old+gain,"admin arena test grants no points");
   var report=PvpProgression.access(server,s->PvpProgression.account(s,p.getUUID()).report);check(PvpProgression.reportTag(report,p.getUUID()).getListOrEmpty("rows").size()==2,"result contains both teams and contributions");
   var acknowledged=new net.minecraft.nbt.CompoundTag();acknowledged.putString("action","report_ack");acknowledged.putString("match",report.id);PvpProgression.action(p,acknowledged);check(PvpProgression.access(server,st->PvpProgression.account(st,p.getUUID()).report)!=null,"closing result retains last report for replay");check(!PvpProgression.showReport(p,false)&&PvpProgression.showReport(p,true),"acknowledged report opens only on explicit replay");
   var training=new ArenaManager.Session(new ArenaManager.Key(ArenaRules.Kind.DUNES,0),0);training.test=true;training.match.teams.put(p.getUUID(),0);training.match.red=500;training.match.ended=true;long balanceBefore=PvpProgression.access(server,st->PvpProgression.account(st,p.getUUID()).points);PvpProgression.finish(training,server);var trainingReport=PvpProgression.access(server,st->PvpProgression.account(st,p.getUUID()).report);check(trainingReport.training&&trainingReport.rows.getFirst().points==0&&PvpProgression.access(server,st->PvpProgression.account(st,p.getUUID()).points)==balanceBefore,"training produces report without reward");PvpProgression.leaving(p,training);check(PvpProgression.access(server,st->PvpProgression.account(st,p.getUUID()).report).unfinished,"manual departure produces partial report");
   com.mmorpg.MMORPG.LOGGER.info("[CODEX CHECKS] PVP_PASS: OP-only creative/deop, displacement immunity, 20 sets/weapons, PvP/PvE stats, purchases/replays/full inventory, unique mount and idempotent contribution-based rewards");
  }finally{d.load(saved);for(int i=0;i<before.size();i++)p.getInventory().setItem(i,before.get(i));if(wasOp)server.getPlayerList().op(identity);else server.getPlayerList().deop(identity);p.setGameMode(oldMode);}
 }
}
